def box_fv_var():
    S('s-boxfv2', 'ארגז הנוסחאות: ערך עתידי בריבית משתנה', 'ארגז הנוסחאות: ערך עתידי, ריבית משתנה מתקופה לתקופה',
      '<div class="card fm"><b>ערך עתידי של סכום יחיד, ריבית משתנה</b><p>' + TX('במילים: הערך הנוכחי, כפול כופל נפרד לכל ריבית: 1 ועוד אותה ריבית, בחזקת מספר התקופות שבהן היא תקפה.') + '</p>' + EQ('FV = PV × (1 + r_{1})^{t_{1}} × (1 + r_{2})^{t_{2}} × ···', 'big') + '<div class="demo">' + TX('מאיה לוותה 200,000 ש״ח ל-10 שנים: 7% ב-3 השנים הראשונות ו-8% ב-7 השנים הבאות. כמה תחזיר? $FV_{10} = 200,000 × (1 + 7%)^{3} × (1 + 8%)^{7} = 419,901.68$') + '</div></div>'
      + legend('FV PV r_{1} t_{1}') + BAND('dg', 'זו הנוסחה שהפעלנו בשאלה 2. כל ריבית מקבלת כופל משלה, והכופלים מוכפלים בשרשרת. אין לחבר ריביות ואין למצע אותן.', 1),
      kick=f'חלק {CUR[0]} · ארגז הנוסחאות')


def box_pv_var():
    S('s-box1v', 'ארגז הנוסחאות: ערך נוכחי בשערי היוון משתנים', 'ארגז הנוסחאות: ערך נוכחי, שערי היוון משתנים',
      '<div class="card fm"><b>ערך נוכחי של סכום יחיד, שערי היוון משתנים</b><p>' + TX('במילים: הערך העתידי, כפול כופל נפרד לכל ריבית, בחזקת מינוס מספר התקופות שלה.') + '</p>' + EQ('PV = FV × (1 + r_{1})^{-t_{1}} × (1 + r_{2})^{-t_{2}} × ···', 'big') + '<div class="demo">' + TX('500,000 ש״ח יתקבלו בעוד 7 שנים: 4% בשנים 1 עד 2, ו-6% בשנים 3 עד 7. כמה הם שווים היום? $PV_{0} = 500,000 × (1 + 4%)^{-2} × (1 + 6%)^{-5} = 345,441.09$') + '</div></div>'
      + legend('PV FV r_{1} t_{1}') + BAND('dg', 'זו הנוסחה שהפעלנו בשאלה 6, והיא תמונת המראה של הנוסחה מן החלק של ערך עתידי בריבית משתנה: אותה שרשרת, רק עם חזקות שליליות.', 1),
      kick=f'חלק {CUR[0]} · ארגז הנוסחאות')


def box_loan():
    S('s-loan', 'משפט ההלוואה', 'משפט ההלוואה',
      '<div class="row eq2 top">'
      + DEF('משפט ההלוואה', 'סכום הלוואה הוא תמיד הערך הנוכחי של החזריה: $LOAN = PMT × PVFA(r,t)$, כש-$LOAN$ (הלוואה) הוא סכום ההלוואה.', 'רונן לווה 500,000 ש״ח, ויחזיר 36 החזרים חודשיים בתום כל חודש, בריבית חודשית של 1%, כמו בשאלה 19. ההחזר שחילצנו שם, 16,607.15 ש״ח, מקיים: $LOAN = 16,607.15 × PVFA(1%,36) = 500,000$.', trm='loan')
      + DEF('יתרת הלוואה', 'בכל מועד, היתרה היא הערך הנוכחי של יתרת ההחזרים באותו מועד. נסמן אותה $B$ (Balance), ואת מועדה במספר קטן: $B_{1}$ היא היתרה בזמן 1.', 'יוסי לווה 173.55 ש״ח, ויחזיר 100 ש״ח בתום כל שנה במשך שנתיים, בריבית 10%. מהי היתרה מיד אחרי ההחזר הראשון? נותר החזר אחד, בזמן 2, ומהוונים אותו שנה אחת ($PV = FV × (1 + r)^{-t}$): $B_{1} = 100 × (1 + 10%)^{-1} = 90.91$. בדיקה: $B_{1} = 173.55 × (1 + 10%) - 100 = 90.91$.', 1, trm='balance') + '</div>'
      + ST(2, EQ('LOAN = PV(payments)', 'big c', key=True), cls='fxs'),
      kick=f'חלק {CUR[0]} · ארגז הנוסחאות')


def box_perp():
    S('s-box3', 'ארגז הנוסחאות: זרם אינסופי', 'ארגז הנוסחאות: זרם כספים אינסופי',
      '<div class="card fm"><b>ערך נוכחי של זרם כספים אינסופי</b><p>' + TX('[[perp|זרם אינסופי]], או צמיתות: תזרים קבוע שנמשך לנצח. במילים: התזרים, חלקי הריבית.') + '</p><div class="eq" dir="ltr">' + M('PVFA(r,∞) = \\f{1}{r}') + '&emsp;' + M('PV_{∞} = PMT × \\f{1}{r}') + '</div><div class="demo">' + TX('הנכס מניב 6,000 ש״ח בתום כל חצי שנה, לצמיתות, והריבית החצי שנתית 5%, כמו בשאלה 22. כמה הוא שווה היום? $PV_{∞} = \\f{6,000}{0.05} = 120,000$') + '</div></div>'
      + legend('PMT r') + BAND('note', 'ערך עתידי של סדרה אינסופית איננו קיים. הוא שואף לאינסוף. אינסופיות שייכת לערך נוכחי בלבד.', 1),
      kick=f'חלק {CUR[0]} · ארגז הנוסחאות')


def rcard(n, t, d, m, go):
    return f'<button class="rcard" data-go="{go}"><div class="n">{n}</div><b>{t}</b><span>{TX(d)}</span><em>{m}</em></button>'


