S('s-box2', 'ארגז הנוסחאות: סדרה קבועה', 'ארגז הנוסחאות: סדרת סכומים קבועה, מה שכבר הדגמנו',
  '<div class="col">'
  + '<div class="card fm"><b>ערך עתידי של סדרה קבועה</b><p>' + TX('במילים: התזרים התקופתי, כפול המקדם: 1 ועוד הריבית בחזקת מספר התשלומים, פחות 1, והכול חלקי הריבית.') + '</p><div class="eq" dir="ltr">' + M('FV_{Series} = PMT × FVFA(r,t)') + '&emsp;&emsp;' + M('FVFA(r,t) = \\f{(1 + r)^{t} - 1}{r}') + '</div><div class="demo">' + TX('דנה הפקידה 100 ש״ח בתום כל שנה במשך 3 שנים, בריבית 10%. כמה עמד לרשותה מיד אחרי ההפקדה השלישית? $FV_{3} = 100 × FVFA(10%,3) = 100 × 3.31 = 331$') + '</div></div>'
  + '<div class="card fm st" data-n="10"><b>ערך נוכחי של סדרה קבועה (סופית)</b><p>' + TX('במילים: התזרים התקופתי, כפול המקדם: 1 פחות 1 ועוד הריבית בחזקת מינוס מספר התשלומים, והכול חלקי הריבית.') + '</p><div class="eq" dir="ltr">' + M('PV_{Series} = PMT × PVFA(r,t)') + '&emsp;&emsp;' + M('PVFA(r,t) = \\f{1 - (1 + r)^{-t}}{r}') + '</div><div class="demo">' + TX('הנכס של אורי מניב 100 ש״ח בתום כל שנה במשך 3 שנים, בריבית 10%. מה שוויו היום? $PV_{0} = 100 × PVFA(10%,3) = 100 × 2.486852 = 248.69$') + '</div></div></div>' + legend('PMT FVFA PVFA r t'),
  kick='חלק 2 · ארגז הנוסחאות')

